function remediationQuestionPrompt(plan: any): string | null {
  const metadata =
    plan?.metadata && typeof plan.metadata === "object"
      ? plan.metadata
      : null;

  const direct = safeStr(
    plan?.questionPrompt ??
      metadata?.questionPrompt,
  );

  if (direct) {
    return direct;
  }

  const description = safeStr(plan?.description);
  const prefix = "Assessment question:";

  if (description.startsWith(prefix)) {
    const remainder = description.slice(prefix.length).trim();
    const scoreMarker = " This control scored ";
    const markerIndex = remainder.indexOf(scoreMarker);

    if (markerIndex >= 0) {
      return remainder.slice(0, markerIndex).trim() || null;
    }

    return remainder || null;
  }

  return null;
}

function vendorEvidenceInstruction(plan: any): string {
  const questionPrompt = remediationQuestionPrompt(plan);

  const requirementContext = questionPrompt
    ? ` The assessment item requiring remediation is: "${questionPrompt}"`
    : "";

  return [
    "Please provide evidence demonstrating that this control gap has been remediated.",
    "Upload supporting documentation or other evidence showing the corrective action implemented and its current operating status.",
    requirementContext,
  ]
    .filter(Boolean)
    .join(" ");
}
function mergePlanDetails(target: any, source: any) {
  const evidence = [
    ...asArray(target.requiredEvidence),
    ...asArray(source?.requiredEvidence),
    ...asArray(source?.evidence),
    ...asArray(source?.evidenceItems),
  ];

  const attestations = [
    ...asArray(target.requiredAttestation),
    ...asArray(source?.requiredAttestation),
    ...asArray(source?.requiredAttestations),
    ...asArray(source?.attestations),
  ];

  return {
    ...target,
    ...source,
    title: safeStr(target?.title) || safeStr(source?.title),
    requiredEvidence: Array.from(new Set(evidence.map(safeStr).filter(Boolean))),
    requiredAttestation: Array.from(new Set(attestations.map(safeStr).filter(Boolean))),
    recommendation: safeStr(target?.recommendation) || safeStr(source?.recommendation),
    releaseImpact: safeStr(target?.releaseImpact) || safeStr(source?.releaseImpact),
    evidenceSignal: safeStr(target?.evidenceSignal) || safeStr(source?.evidenceSignal),
  };
}

function extractPlans(responses: any) {
  const primaryPools = [
    responses?.truvernRemediation?.plans,
    responses?.structuredAssessment?.truvernRemediation?.plans,
    responses?.generatedDraft?.structuredAssessment?.truvernRemediation?.plans,
    responses?.remediationPlans,
  ];

  const primary = primaryPools.flatMap(asArray);


    // Existing drafts may predate generated remediation-plan persistence.
  // When no explicit plans exist, project the already-persisted canonical
  // findings into remediation plans without rerunning findings intelligence.
  const canonicalFindingPools = [
    responses?.canonicalGovernanceArtifact?.findings,
    responses?.canonicalFindings,
    responses?.generatedDraft?.canonicalGovernanceArtifact?.findings,
    responses?.generatedDraft?.canonicalFindings,
    responses?.truvernReviewerIntelligence?.findings,
  ];

  const canonicalFindings =
    canonicalFindingPools
      .map((pool) => asArray(pool))
      .find((pool) => pool.length > 0) || [];

  if (canonicalFindings.length > 0) {
    const seen = new Set<string>();

    return canonicalFindings
      .filter((finding: any) => {
        if (!finding || typeof finding !== "object") return false;

        if (finding.remediationRequired === false) return false;

        const severity =
          safeStr(finding.severity).toUpperCase();

        return [
          "CRITICAL",
          "HIGH",
          "MODERATE",
          "MEDIUM",
        ].includes(severity);
      })
      .map((finding: any, index: number) => {
        const title =
          safeStr(finding.title) ||
          safeStr(finding.controlTitle) ||
          safeStr(finding.control) ||
          safeStr(finding.controlId) ||
          `Governance finding ${index + 1}`;

        const description =
          safeStr(finding.description) ||
          safeStr(finding.summary) ||
          safeStr(finding.finding) ||
          safeStr(finding.rationale) ||
          `Remediation is required for ${title}.`;

        const requiredEvidence = [
          ...asArray(finding.requiredEvidence),
          ...asArray(finding.evidenceRequired),
          ...asArray(finding.evidence),
          ...asArray(finding.evidenceItems),
        ]
          .map(safeStr)
          .filter(Boolean);

        const requiredAttestation = [
          ...asArray(finding.requiredAttestation),
          ...asArray(finding.requiredAttestations),
          ...asArray(finding.attestationRequired),
          ...asArray(finding.attestations),
        ]
          .map(safeStr)
          .filter(Boolean);

        const recommendation =
          safeStr(finding.recommendation) ||
          safeStr(finding.remediation) ||
          safeStr(finding.remediationRecommendation) ||
          safeStr(finding.recommendedAction) ||
          description;

        return normalizePlan(
          {
            ...finding,
            title,
            description,
            requiredEvidence,
            requiredAttestation,
            recommendation,
            releaseImpact:
              safeStr(finding.releaseImpact) ||
              "Remediation must be reviewed before governance release.",
            evidenceSignal:
              safeStr(finding.evidenceSignal) ||
              "Evidence is required to validate remediation.",
            severity:
              safeStr(finding.severity).toUpperCase(),
            sourceKey:
              safeStr(finding.sourceKey) ||
              safeStr(finding.id) ||
              safeStr(finding.controlId) ||
              `canonical-finding-${index + 1}`,
          },
          index,
        );
      })
      .filter((plan) => {
        const key =
          `${safeStr(plan.sourceKey)}|${plan.title.toLowerCase()}`;

        if (!plan.title || seen.has(key)) return false;

        seen.add(key);
        return true;
      });
  }

  // R82G: canonical remediation-required findings are the
  // completeness authority. Generated remediation plans remain
  // available only when canonical findings are absent.

  if (primary.length > 0) {
    const seen = new Set<string>();

    return primary
      .map((plan, index) => normalizePlan(plan, index))
      .filter((plan) => {
        const key = safeStr(plan.sourceKey) || plan.title.toLowerCase();
        if (!key || seen.has(key)) return false;
        seen.add(key);
        return true;
      });
  }

const fallback = [
    ...asArray(responses?.conditionsAndFollowUps),
    ...asArray(responses?.structuredAssessment?.conditionsAndFollowUps),
  ];

  const grouped: any[] = [];
  let current: any = null;

  for (const item of fallback) {
    const rawTitle =
      typeof item === "string"
        ? item
        : safeStr(item?.title ?? item?.findingTitle ?? item?.control ?? item?.controlId);

    const text = safeStr(rawTitle);
    const lower = text.toLowerCase();

    const isParentFinding =
      lower.includes("governance gap") ||
      lower.startsWith("vendor must resolve:") ||
      lower.startsWith("resolve:");

    const isEvidenceLine = lower.startsWith("required evidence:");
    const isAttestationLine =
      lower.startsWith("required attestation:") ||
      lower.startsWith("required attestations:");

    if (isParentFinding) {
      const cleanTitle = text
        .replace(/^vendor must resolve:\s*/i, "")
        .replace(/^resolve:\s*/i, "")
        .trim();

      current = typeof item === "object" && item
        ? { ...item, title: cleanTitle || text }
        : { title: cleanTitle || text };

      grouped.push(current);
      continue;
    }

    if ((isEvidenceLine || isAttestationLine) && current) {
      const cleaned = text
        .replace(/^required evidence:\s*/i, "")
        .replace(/^required attestations?:\s*/i, "")
        .trim();

      if (isEvidenceLine) {
        current.requiredEvidence = [
          ...asArray(current.requiredEvidence),
          ...splitListText(cleaned),
        ];
      }

      if (isAttestationLine) {
        current.requiredAttestation = [
          ...asArray(current.requiredAttestation),
          ...splitListText(cleaned),
        ];
      }

      continue;
    }

    if (current && lower.includes("reviewer validation")) {
      current.requiredAttestation = [
        ...asArray(current.requiredAttestation),
        "Reviewer validation before governance release",
      ];
      continue;
    }

    // Keep generic operational follow-ups out of vendor remediation packages.
    if (
      lower.startsWith("continue ") ||
      lower.startsWith("maintain ") ||
      lower.startsWith("notify customers")
    ) {
      continue;
    }

    if (typeof item === "object" && item) {
      current = mergePlanDetails(current || {}, item);
      if (!grouped.includes(current)) grouped.push(current);
    }
  }

  const seen = new Set<string>();
  return grouped
    .map((plan, index) => normalizePlan(plan, index))
    .filter((plan) => {
      const key = safeStr(plan.sourceKey) || plan.title.toLowerCase();
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

export async function POST(_req: Request, props: Props) {
  try {
    const actor = await requireReviewerAccess();

    const { userId } = await auth();
    const resolved = await props.params;
    const assignmentId = Number(resolved?.id);

    if (!Number.isFinite(assignmentId) || assignmentId <= 0) {
      return NextResponse.json({ ok: false, error: "Assignment id required." }, { status: 400 });
    }
    const assignment =
      await findReviewAssignment({
        where: {
          id: assignmentId,
        },
        select: {
          id: true,
          vendorId: true,
          organizationId: true,
        },
      });

    if (
      assignment &&
      actor.role !== "OPS" &&
      actor.organizationId != null &&
      actor.organizationId !== assignment.organizationId
    ) {
      return NextResponse.json(
        { ok: false, error: "Forbidden." },
        { status: 403 },
      );
    }
    const latestResponse =
      assignment
        ? await findLatestReviewResponse(assignment.id)
        : null;

    const row =
      assignment
        ? {
            assignmentId: assignment.id,
            vendorId: assignment.vendorId,
            organizationId: assignment.organizationId,
            responses: latestResponse?.responses ?? null,
          }
        : null;

    if (!row) {
      return NextResponse.json({ ok: false, error: "Review assignment not found." }, { status: 404 });
    }

    const responses = safeJson(row.responses);
    const rawPlans = extractPlans(responses);

    if (rawPlans.length === 0) {
      return NextResponse.json({
        ok: true,
        createdCount: 0,
        skippedCount: 0,
        message: "No generated remediation plans found.",
      });
    }

    // ----------------------------------------------------------
    // Deterministic logical-plan reconciliation.
    //
    // Different generated source keys must not allow duplicate
    // logical remediation work to pass silently. Same-title plans
    // are collapsed only when their remediation semantics match.
    // Otherwise publishing fails closed before any database write.
    // ----------------------------------------------------------

    function planSemanticSignature(plan: any) {
      return JSON.stringify({
        title: safeStr(plan.title).toLowerCase(),
        kind: safeStr(plan.kind).toUpperCase(),
        severity: safeStr(plan.severity).toUpperCase(),
        questionPrompt: safeStr(plan.questionPrompt),
        description: safeStr(plan.description),
        recommendation: safeStr(plan.recommendation),
        releaseImpact: safeStr(plan.releaseImpact),
        evidenceSignal: safeStr(plan.evidenceSignal),
        requiredEvidence: asArray(plan.requiredEvidence),
        requiredAttestation: asArray(plan.requiredAttestation),
      });
    }

    const planByLogicalTitle =
      new Map<string, any>();

    for (const plan of rawPlans) {
      const logicalTitle =
        safeStr(plan.title).toLowerCase();

      if (!logicalTitle) {
        continue;
      }

      const prior =
        planByLogicalTitle.get(logicalTitle);

      if (!prior) {
        planByLogicalTitle.set(
          logicalTitle,
          plan,
        );
        continue;
      }

      if (
        planSemanticSignature(prior) !==
        planSemanticSignature(plan)
      ) {
        return NextResponse.json(
          {
            ok: false,
            error:
              "Remediation reconciliation conflict.",
            reason:
              "Multiple generated remediation plans share a logical title but differ semantically.",
            title: plan.title,
          },
          {
            status: 409,
          },
        );
      }
    }

    const plans =
      Array.from(
        planByLogicalTitle.values(),
      );

    // ----------------------------------------------------------
    // Read-only reconciliation preflight.
    //
    // Every plan is resolved before the first package or evidence
    // request mutation occurs.
    // ----------------------------------------------------------

    const reconciliation: Array<{
      plan: any;
      remediationPayload: Prisma.InputJsonValue;
      existingRequestId: number | null;
      existingPackage:
        | {
            id: number;
            sourceKey: string;
            title: string;
            severity: string | null;
            dueAt: Date | null;
            payload: any;
          }
        | null;
    }> = [];

    for (const plan of plans) {
      const existingRequests =
        await findEvidenceRequests({
          where: {
            vendorId:
              Number(row.vendorId),
            organizationId:
              Number(row.organizationId),
            status: {
              not: "CANCELLED",
            },
            OR: [
              {
                title: {
                  equals: plan.title,
                  mode: "insensitive",
                },
              },
              {
                AND: [
                  {
                    title: null,
                  },
                  {
                    label: {
                      equals: plan.title,
                      mode: "insensitive",
                    },
                  },
                ],
              },
            ],
          },
          select: {
            id: true,
          },
          orderBy: {
            id: "asc",
          },
          take: 2,
        });

      if (existingRequests.length > 1) {
        return NextResponse.json(
          {
            ok: false,
            error:
              "Remediation reconciliation conflict.",
            reason:
              "Multiple active evidence requests match the same remediation title.",
            title: plan.title,
            evidenceRequestIds:
              existingRequests.map(
                (item) => item.id,
              ),
          },
          {
            status: 409,
          },
        );
      }

      const existingRequestId =
        existingRequests.length === 1
          ? Number(
              existingRequests[0].id,
            )
          : null;

      const linkedPackageRows =
        existingRequestId != null
          ? await findRemediationPackages({
              where: {
                reviewAssignmentId:
                  assignmentId,
                evidenceRequestId:
                  existingRequestId,
              },
              select: {
                id: true,
                sourceKey: true,
                title: true,
                severity: true,
                dueAt: true,
                payload: true,
              },
              orderBy: {
                id: "asc",
              },
            })
          : [];

      let existingPackage:
        | {
            id: number;
            sourceKey: string;
            title: string;
            severity: string | null;
            dueAt: Date | null;
            payload: any;
          }
        | null = null;

      if (linkedPackageRows.length === 1) {
        existingPackage =
          linkedPackageRows[0];
      } else if (
        linkedPackageRows.length > 1
      ) {
        const activeOverridePackages =
          linkedPackageRows.filter(
            (pkg) =>
              safeJson(pkg.payload)
                ?.reviewerOverride
                ?.active === true,
          );

        if (
          activeOverridePackages.length !== 1
        ) {
          return NextResponse.json(
            {
              ok: false,
              error:
                "Remediation reconciliation conflict.",
              reason:
                "Multiple remediation packages are linked to one evidence request and no unique reviewer override identifies the authoritative package.",
              title: plan.title,
              evidenceRequestId:
                existingRequestId,
              packageIds:
                linkedPackageRows.map(
                  (pkg) => pkg.id,
                ),
              activeOverridePackageIds:
                activeOverridePackages.map(
                  (pkg) => pkg.id,
                ),
            },
            {
              status: 409,
            },
          );
        }

        existingPackage =
          activeOverridePackages[0];
      }

      if (!existingPackage) {
        const sourceKeyPackageRows =
          await findRemediationPackages({
            where: {
              reviewAssignmentId:
                assignmentId,
              sourceKey:
                plan.sourceKey!,
            },
            select: {
              id: true,
              sourceKey: true,
              title: true,
              severity: true,
              dueAt: true,
              payload: true,
            },
            orderBy: {
              id: "asc",
            },
            take: 2,
          });

        if (
          sourceKeyPackageRows.length > 1
        ) {
          return NextResponse.json(
            {
              ok: false,
              error:
                "Remediation reconciliation conflict.",
              reason:
                "Multiple remediation packages match the same assignment/sourceKey identity.",
              title: plan.title,
              sourceKey:
                plan.sourceKey,
              packageIds:
                sourceKeyPackageRows.map(
                  (pkg) => pkg.id,
                ),
            },
            {
              status: 409,
            },
          );
        }

        existingPackage =
          sourceKeyPackageRows[0] ??
          null;
      }

      const remediationPayload =
        JSON.parse(
          JSON.stringify({
            sourceKey:
              plan.sourceKey,
            questionPrompt:
              plan.questionPrompt,
            title:
              plan.title,
            summary:
              plan.description,
            requiredEvidence:
              plan.requiredEvidence,
            requiredAttestations:
              plan.requiredAttestation,
            recommendation:
              plan.recommendation,
            releaseImpact:
              plan.releaseImpact,
            evidenceSignal:
              plan.evidenceSignal,
            severity:
              plan.severity,
          }),
        ) as Prisma.InputJsonValue;

      reconciliation.push({
        plan,
        remediationPayload,
        existingRequestId,
        existingPackage,
      });
    }

    // ----------------------------------------------------------
    // Mutation phase.
    //
    // No execution reaches this point unless every plan completed
    // deterministic preflight successfully.
    // ----------------------------------------------------------

    const created: number[] = [];
    const skipped: string[] = [];

    for (
      const decision of reconciliation
    ) {
      const {
        plan,
        remediationPayload,
        existingRequestId,
        existingPackage,
      } = decision;

      const existingPackagePayload =
        safeJson(
          existingPackage?.payload,
        );

      const reviewerOverrideActive =
        existingPackagePayload
          ?.reviewerOverride
          ?.active === true;

      const preservedReviewerPayload =
        reviewerOverrideActive
          ? (
              JSON.parse(
                JSON.stringify({
                  ...existingPackagePayload,
                  latestGeneratedBaseline:
                    remediationPayload,
                  latestGeneratedAt:
                    new Date()
                      .toISOString(),
                }),
              ) as Prisma.InputJsonValue
            )
          : null;

      const remediationPackage =
        existingPackage
          ? await updateRemediationPackage({
              where: {
                id:
                  existingPackage.id,
              },
              data:
                reviewerOverrideActive &&
                preservedReviewerPayload
                  ? {
                      title:
                        existingPackage.title,
                      severity:
                        existingPackage.severity,
                      dueAt:
                        existingPackage.dueAt,
                      payload:
                        preservedReviewerPayload,
                    }
                  : {
                      title:
                        plan.title,
                      severity:
                        plan.severity,
                      dueAt:
                        plan.dueAt,
                      payload:
                        remediationPayload,
                    },
              select: {
                id: true,
              },
            })
          : await upsertRemediationPackage({
              where: {
                reviewAssignmentId_sourceKey:
                  {
                    reviewAssignmentId:
                      assignmentId,
                    sourceKey:
                      plan.sourceKey!,
                  },
              },
              create: {
                reviewAssignmentId:
                  assignmentId,
                vendorId:
                  Number(row.vendorId),
                organizationId:
                  Number(
                    row.organizationId,
                  ),
                sourceKey:
                  plan.sourceKey!,
                title:
                  plan.title,
                status:
                  "REQUESTED",
                severity:
                  plan.severity,
                dueAt:
                  plan.dueAt,
                payload:
                  remediationPayload,
              },
              update: {
                title:
                  plan.title,
                severity:
                  plan.severity,
                dueAt:
                  plan.dueAt,
                payload:
                  remediationPayload,
              },
              select: {
                id: true,
              },
            });

      if (
        existingRequestId != null
      ) {
        const packageId =
          remediationPackage.id;

        if (
          !Number.isFinite(packageId)
        ) {
          throw new Error(
            "Remediation package id missing while linking existing evidence request.",
          );
        }

        await updateRemediationPackage({
          where: {
            id: packageId,
          },
          data: {
            evidenceRequestId:
              existingRequestId,
          },
        });

        skipped.push(
          plan.title,
        );

        continue;
      }

      const insertedEvidenceRequest =
        await createEvidenceRequest({
          data: {
            vendorId:
              Number(row.vendorId),
            organizationId:
              Number(
                row.organizationId,
              ),
            requestedBy:
              userId ||
              "truvern-findings-engine",
            kind:
              plan.kind as EvidenceRequestKind,
            label:
              plan.title.slice(
                0,
                240,
              ),
            title:
              plan.title,
            description:
              vendorEvidenceInstruction(
                plan,
              ),
            dueAt:
              plan.dueAt,
            status:
              "REQUESTED",
            requestedAt:
              new Date(),
            notes:
              "Auto-created by Truvern Findings Engine.",
          },
          select: {
            id: true,
          },
        });

      const evidenceRequestId =
        insertedEvidenceRequest.id;

      created.push(
        evidenceRequestId,
      );

      const packageId =
        remediationPackage.id;

      if (
        !Number.isFinite(packageId)
      ) {
        throw new Error(
          "Remediation package id missing while linking created evidence request.",
        );
      }

      await updateRemediationPackage({
        where: {
          id: packageId,
        },
        data: {
          evidenceRequestId,
        },
      });
    }

    return NextResponse.json({
      ok: true,
      createdCount:
        created.length,
      createdIds:
        created,
      skippedCount:
        skipped.length,
      skipped,
      message:
        `Published ${created.length} generated remediation request(s).`,
    });
  } catch (error: any) {
    const authError =
      governanceAuthErrorResponse(error);

    if (authError) {
      return authError;
    }
    console.error("Auto-publish remediation failed:", error);
    return NextResponse.json(
      { ok: false, error: safeStr(error?.message) || "Failed to publish remediation requests." },
      { status: 500 },
    );
  }
}








